extends Node3D

func build() -> void:
	var mesh_library := MeshLibrary.new()
	var colors := [Color.RED, Color.GREEN, Color.BLUE]
	for i in range(3):
		mesh_library.create_item(i)
		var mesh := BoxMesh.new()
		mesh.size = Vector3(1, 1, 1)
		var material := StandardMaterial3D.new()
		material.albedo_color = colors[i]
		mesh.surface_set_material(0, material)
		mesh_library.set_item_mesh(i, mesh)

	var grid_map := $GridMap as GridMap
	grid_map.mesh_library = mesh_library
	grid_map.clear()

	var file := FileAccess.open("res://data/level.json", FileAccess.READ)
	if not file:
		push_error("Could not open level.json")
		return
	var json_text := file.get_as_text()
	file.close()
	var json := JSON.new()
	var error := json.parse(json_text)
	if error == OK:
		var data := json.data as Dictionary
		if data.has("cells"):
			for cell in data.cells:
				grid_map.set_cell_item(Vector3i(cell.x, cell.y, cell.z), cell.id)

func place(item_id: int, gx: int, gy: int, gz: int) -> void:
	$GridMap.set_cell_item(Vector3i(gx, gy, gz), item_id)

func remove(gx: int, gy: int, gz: int) -> void:
	$GridMap.set_cell_item(Vector3i(gx, gy, gz), GridMap.INVALID_CELL_ITEM)

func get_item(gx: int, gy: int, gz: int) -> int:
	return $GridMap.get_cell_item(Vector3i(gx, gy, gz))
